//! go-file: pkg/parser/charset/charset.go
//!
//! Port of Go TiDB v8.5.8 `pkg/parser/charset/charset.go` (block D02.2), with the GBK
//! encoder of `encoding_gbk.go` that `pkg/util/collate` uses ([`encoding_gbk`]).
//!
//! The lexer's charset lookups in `crate::charset` predate this module (a subset written
//! for the parser port); this module is the line-by-line port that the collation code
//! (D01.9) and the blocks above it call. The tables are generated by the tracker's `rsgen`
//! (`charset_data.rs`).
//!
//! Go's package state (`CharacterSetInfos`, the collation maps) is mutable: `AddCharset`,
//! `AddCollation` and `collate.SetNewCollationEnabledForTest` change it, and the
//! `*Collation` / `*Charset` pointers in the maps are shared (changing `IsDefault` through
//! one map is seen through the others). Here the state is behind `RwLock`s, the values
//! are `Arc`s, and the fields Go writes after `init` (`Collation.IsDefault`,
//! `Charset.DefaultCollation`, `Charset.Collations`) have interior mutability.

#![allow(non_upper_case_globals)]

pub mod encoding_gbk;

#[rustfmt::skip]
mod charset_data;
#[rustfmt::skip]
mod gbk_encode_data;

use std::collections::HashMap;
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::{Arc, LazyLock, RwLock, RwLockReadGuard};

use tidb_base::gofmt::Arg;
use tidb_base::gostd::to_lower;
use tidb_base::{Error, errors, mysql, terror};

/// ErrUnknownCollation is unknown collation.
pub static ErrUnknownCollation: LazyLock<Error> =
    LazyLock::new(|| terror::ClassDDL.new_std(mysql::ErrUnknownCollation));
/// ErrCollationCharsetMismatch is collation charset mismatch.
pub static ErrCollationCharsetMismatch: LazyLock<Error> =
    LazyLock::new(|| terror::ClassDDL.new_std(mysql::ErrCollationCharsetMismatch));

/// PadSpace is to mark that trailing spaces are insignificant in comparisons
pub const PadSpace: &str = "PAD SPACE";
/// PadNone is to mark that trailing spaces are significant in comparisons
pub const PadNone: &str = "NO PAD";

/// Charset is a charset.
/// Now we only support MySQL.
#[derive(Debug)]
pub struct Charset {
    pub name: String,
    default_collation: RwLock<String>,
    collations: RwLock<HashMap<String, Arc<Collation>>>,
    pub desc: String,
    pub maxlen: isize,
}

impl Charset {
    /// `&Charset{Name, DefaultCollation, make(map[string]*Collation), Desc, Maxlen}`.
    // glue: Go struct literal
    pub fn new(name: &str, default_collation: &str, desc: &str, maxlen: isize) -> Charset {
        Charset {
            name: name.to_owned(),
            default_collation: RwLock::new(default_collation.to_owned()),
            collations: RwLock::new(HashMap::new()),
            desc: desc.to_owned(),
            maxlen,
        }
    }

    /// The field `DefaultCollation`.
    // glue: Go field read
    pub fn default_collation(&self) -> String {
        self.default_collation.read().unwrap().clone()
    }

    /// `cs.DefaultCollation = name`.
    // glue: Go field write
    pub fn set_default_collation(&self, name: &str) {
        *self.default_collation.write().unwrap() = name.to_owned();
    }

    /// The field `Collations` (read).
    // glue: Go field read
    pub fn collations(&self) -> RwLockReadGuard<'_, HashMap<String, Arc<Collation>>> {
        self.collations.read().unwrap()
    }
}

/// Collation is a collation.
/// Now we only support MySQL.
#[derive(Debug)]
pub struct Collation {
    pub id: isize,
    pub charset_name: String,
    pub name: String,
    is_default: AtomicBool,
    pub sortlen: isize,
    pub pad_attribute: String,
}

impl Collation {
    /// `&Collation{ID, CharsetName, Name, IsDefault, Sortlen, PadAttribute}`.
    // glue: Go struct literal
    pub fn new(
        id: isize,
        charset_name: &str,
        name: &str,
        is_default: bool,
        sortlen: isize,
        pad_attribute: &str,
    ) -> Collation {
        Collation {
            id,
            charset_name: charset_name.to_owned(),
            name: name.to_owned(),
            is_default: AtomicBool::new(is_default),
            sortlen,
            pad_attribute: pad_attribute.to_owned(),
        }
    }

    /// The field `IsDefault`.
    // glue: Go field read
    pub fn is_default(&self) -> bool {
        self.is_default.load(Ordering::Relaxed)
    }

    /// `c.IsDefault = v` (seen by every holder of the collation, like Go's shared pointer).
    // glue: Go field write
    pub fn set_is_default(&self, v: bool) {
        self.is_default.store(v, Ordering::Relaxed);
    }
}

/// A row of the generated `collations` table (Go's `*Collation` literal).
// glue: generated table row
pub(crate) struct CollationDef {
    pub(crate) id: isize,
    pub(crate) charset_name: &'static str,
    pub(crate) name: &'static str,
    pub(crate) is_default: bool,
    pub(crate) sortlen: isize,
    pub(crate) pad_attribute: &'static str,
}

/// A value of the generated `charsets` table (Go's `*Charset` literal, `Collations` empty).
// glue: generated table row
pub(crate) struct CharsetDef {
    pub(crate) name: &'static str,
    pub(crate) default_collation: &'static str,
    pub(crate) desc: &'static str,
    pub(crate) maxlen: isize,
}

/// The package-level maps of charset.go, filled by `init`.
// glue: Go package variables collationsIDMap, collationsNameMap, supportedCollations, charsets
struct State {
    collations_id_map: HashMap<isize, Arc<Collation>>,
    collations_name_map: HashMap<String, Arc<Collation>>,
    supported_collations: Vec<Arc<Collation>>,
    charsets: HashMap<String, Arc<Charset>>,
}

static state: LazyLock<RwLock<State>> = LazyLock::new(|| {
    let s = RwLock::new(State {
        collations_id_map: HashMap::new(),
        collations_name_map: HashMap::new(),
        supported_collations: Vec::with_capacity(supportedCollationNames.len()),
        charsets: charset_data::charsets
            .iter()
            .map(|(k, c)| {
                (
                    k.to_string(),
                    Arc::new(Charset::new(c.name, c.default_collation, c.desc, c.maxlen)),
                )
            })
            .collect(),
    });
    init(&s);
    s
});

// CharacterSetInfos contains all the supported charsets (see character_set_infos).
static CharacterSetInfos: LazyLock<RwLock<HashMap<String, Arc<Charset>>>> = LazyLock::new(|| {
    let m = [
        (CharsetUTF8, CollationUTF8, "UTF-8 Unicode", 3),
        (CharsetUTF8MB4, CollationUTF8MB4, "UTF-8 Unicode", 4),
        (CharsetASCII, CollationASCII, "US ASCII", 1),
        (CharsetLatin1, CollationLatin1, "Latin1", 1),
        (CharsetBin, CollationBin, "binary", 1),
        (
            CharsetGBK,
            CollationGBKBin,
            "Chinese Internal Code Specification",
            2,
        ),
    ]
    .into_iter()
    .map(|(n, c, d, l)| (n.to_owned(), Arc::new(Charset::new(n, c, d, l))))
    .collect();
    RwLock::new(m)
});

// All the names supported collations should be in the following table.
static supportedCollationNames: [&str; 6] = [
    CollationUTF8,
    CollationUTF8MB4,
    CollationASCII,
    CollationLatin1,
    CollationBin,
    CollationGBKBin,
];

/// TiFlashSupportedCharsets is a map which contains TiFlash supports charsets.
pub static TiFlashSupportedCharsets: [&str; 5] = [
    CharsetUTF8,
    CharsetUTF8MB4,
    CharsetASCII,
    CharsetLatin1,
    CharsetBin,
];

/// The state after `init`; `CharacterSetInfos` is forced first (init writes into it).
// glue: Go package initialisation order
fn st() -> &'static RwLock<State> {
    LazyLock::force(&CharacterSetInfos);
    &state
}

/// CharacterSetInfos contains all the supported charsets.
///
/// Go's package variable; the accessor runs the package `init` first (which fills the
/// charsets' `Collations`).
// glue: Go package variable CharacterSetInfos
pub fn character_set_infos() -> &'static RwLock<HashMap<String, Arc<Charset>>> {
    let _ = st();
    &CharacterSetInfos
}

/// GetSupportedCharsets gets descriptions for all charsets supported so far.
// go: GetSupportedCharsets L1
pub fn get_supported_charsets() -> Vec<Arc<Charset>> {
    let _ = st();
    let mut charsets: Vec<Arc<Charset>> = CharacterSetInfos
        .read()
        .unwrap()
        .values()
        .cloned()
        .collect();

    // sort charset by name.
    charsets.sort_by(|i, j| i.name.cmp(&j.name));
    charsets
}

/// GetSupportedCollations gets information for all collations supported so far.
// go: GetSupportedCollations L1
pub fn get_supported_collations() -> Vec<Arc<Collation>> {
    st().read().unwrap().supported_collations.clone()
}

/// ValidCharsetAndCollation checks the charset and the collation validity
/// and returns a boolean.
// go: ValidCharsetAndCollation L1
pub fn valid_charset_and_collation(cs: &str, co: &str) -> bool {
    // We will use utf8 as a default charset.
    let mut cs = cs;
    if cs.is_empty() || cs == CharsetUTF8MB3 {
        cs = CharsetUTF8;
    }
    let (chs, err) = get_charset_info(cs);
    if err.is_err() {
        return false;
    }
    let chs = chs.expect("charset with no error");

    if co.is_empty() {
        return true;
    }
    let co = utf8_alias(&to_lower(co));
    chs.collations().contains_key(&co)
}

/// GetDefaultCollationLegacy is compatible with the charset support in old version parser.
// go: GetDefaultCollationLegacy L1 [M-ERR]
pub fn get_default_collation_legacy(charset: &str) -> Result<String, Error> {
    match to_lower(charset).as_str() {
        CharsetUTF8MB3 => get_default_collation(CharsetUTF8),
        CharsetUTF8 | CharsetUTF8MB4 | CharsetASCII | CharsetLatin1 | CharsetBin => {
            get_default_collation(charset)
        }
        _ => Err(errors::errorf(
            "Unknown charset %s",
            &[Arg::from(charset.to_owned())],
        )),
    }
}

/// GetDefaultCollation returns the default collation for charset.
// go: GetDefaultCollation L1 [M-ERR]
pub fn get_default_collation(charset: &str) -> Result<String, Error> {
    let (cs, err) = get_charset_info(charset);
    err?;
    Ok(cs.expect("charset with no error").default_collation())
}

/// GetDefaultCharsetAndCollate returns the default charset and collation.
// go: GetDefaultCharsetAndCollate L1
pub fn get_default_charset_and_collate() -> (&'static str, &'static str) {
    (mysql::DefaultCharset, mysql::DefaultCollationName)
}

/// GetCharsetInfo returns charset and collation for cs as name.
///
/// Go returns the charset together with the error for a MySQL charset that TiDB does not
/// support (`Unsupported charset`).
// go: GetCharsetInfo L1 [M-ERR, M-ERRVAL]
pub fn get_charset_info(cs: &str) -> (Option<Arc<Charset>>, Result<(), Error>) {
    let st = st();
    let mut cs = cs;
    if to_lower(cs) == CharsetUTF8MB3 {
        cs = CharsetUTF8;
    }

    if let Some(c) = CharacterSetInfos.read().unwrap().get(&to_lower(cs)) {
        return (Some(c.clone()), Ok(()));
    }

    if let Some(c) = st.read().unwrap().charsets.get(&to_lower(cs)) {
        return (
            Some(c.clone()),
            Err(errors::errorf(
                "Unsupported charset %s",
                &[Arg::from(cs.to_owned())],
            )),
        );
    }

    (
        None,
        Err(errors::errorf(
            "Unknown charset %s",
            &[Arg::from(cs.to_owned())],
        )),
    )
}

/// GetCharsetInfoByID returns charset and collation for id as cs_number.
// go: GetCharsetInfoByID L1 [M-ERR, M-ERRVAL]
pub fn get_charset_info_by_id(co_id: isize) -> (String, String, Result<(), Error>) {
    if co_id == mysql::DefaultCollationID {
        return (
            mysql::DefaultCharset.to_owned(),
            mysql::DefaultCollationName.to_owned(),
            Ok(()),
        );
    }
    if let Some(collation) = st().read().unwrap().collations_id_map.get(&co_id) {
        return (
            collation.charset_name.clone(),
            collation.name.clone(),
            Ok(()),
        );
    }

    log::warn!(
        "unable to get collation name from collation ID, return default charset and collation instead ID={co_id}"
    );
    (
        mysql::DefaultCharset.to_owned(),
        mysql::DefaultCollationName.to_owned(),
        Err(errors::errorf(
            "Unknown collation id %d",
            &[Arg::from(co_id)],
        )),
    )
}

// go: utf8Alias L1
fn utf8_alias(csname: &str) -> String {
    match csname {
        "utf8mb3_bin" => "utf8_bin",
        "utf8mb3_unicode_ci" => "utf8_unicode_ci",
        "utf8mb3_general_ci" => "utf8_general_ci",
        _ => csname,
    }
    .to_owned()
}

/// GetCollationByName returns the collation by name.
// go: GetCollationByName L1 [M-ERR]
pub fn get_collation_by_name(name: &str) -> Result<Arc<Collation>, Error> {
    let csname = utf8_alias(&to_lower(name));
    match st().read().unwrap().collations_name_map.get(&csname) {
        Some(collation) => Ok(collation.clone()),
        None => Err(ErrUnknownCollation.gen_with_stack_by_args(vec![Arg::from(name.to_owned())])),
    }
}

/// GetCollationByID returns collations by given id.
// go: GetCollationByID L1 [M-ERR]
pub fn get_collation_by_id(id: isize) -> Result<Arc<Collation>, Error> {
    match st().read().unwrap().collations_id_map.get(&id) {
        Some(collation) => Ok(collation.clone()),
        None => Err(errors::errorf("Unknown collation id %d", &[Arg::from(id)])),
    }
}

