/// AddCharset adds a new charset.
/// Use only when adding a custom charset to the parser.
// go: AddCharset L1
pub fn add_charset(c: Arc<Charset>) {
    let _ = st();
    CharacterSetInfos.write().unwrap().insert(c.name.clone(), c);
}

/// RemoveCharset remove a charset.
/// Use only when remove a custom charset to the parser.
// go: RemoveCharset L1
pub fn remove_charset(c: &str) {
    let st = st();
    CharacterSetInfos.write().unwrap().remove(c);
    // Go removes while ranging over the indexes of the original slice: an element
    // shifted into index i is not examined again.
    let mut s = st.write().unwrap();
    // Like Go, indexing past the shortened slice panics.
    let n = s.supported_collations.len();
    for i in 0..n {
        if s.supported_collations[i].name == c {
            s.supported_collations.remove(i);
        }
    }
}

/// AddCollation adds a new collation.
/// Use only when adding a custom collation to the parser.
// go: AddCollation L1
pub fn add_collation(c: Arc<Collation>) {
    add_collation_to(st(), c);
}

// go-part: AddCollation
fn add_collation_to(st: &RwLock<State>, c: Arc<Collation>) {
    let mut s = st.write().unwrap();
    s.collations_id_map.insert(c.id, c.clone());
    s.collations_name_map.insert(c.name.clone(), c.clone());

    if supportedCollationNames.contains(&c.name.as_str()) {
        add_supported_collation_to(&mut s, c.clone());
    }

    if let Some(charset) = CharacterSetInfos.read().unwrap().get(&c.charset_name) {
        charset
            .collations
            .write()
            .unwrap()
            .insert(c.name.clone(), c.clone());
    }

    if let Some(charset) = s.charsets.get(&c.charset_name) {
        charset
            .collations
            .write()
            .unwrap()
            .insert(c.name.clone(), c.clone());
    }
}

/// AddSupportedCollation adds a new collation into supportedCollations.
/// Use only when adding a custom collation to the parser.
// go: AddSupportedCollation L1
pub fn add_supported_collation(c: Arc<Collation>) {
    add_supported_collation_to(&mut st().write().unwrap(), c);
}

// go-part: AddSupportedCollation
fn add_supported_collation_to(s: &mut State, c: Arc<Collation>) {
    s.supported_collations.push(c);
}

/// init method always puts to the end of file.
// go: init L1
fn init(st: &RwLock<State>) {
    for c in &charset_data::collations {
        add_collation_to(
            st,
            Arc::new(Collation::new(
                c.id,
                c.charset_name,
                c.name,
                c.is_default,
                c.sortlen,
                c.pad_attribute,
            )),
        );
    }
}
